211	func (s *APIV1Service) UpdateShortcut(ctx context.Context, request *v1pb.UpdateShortcutRequest) (*v1pb.Shortcut, error) {
212		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Shortcut.Name)
213		if err != nil {
214			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
215		}
216		userID := user.ID
217	
218		currentUser, err := s.fetchCurrentUser(ctx)
219		if err != nil {
220			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
221		}
222		if currentUser == nil || currentUser.ID != userID {
223			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
224		}
225		if request.UpdateMask == nil || len(request.UpdateMask.Paths) == 0 {
226			return nil, status.Errorf(codes.InvalidArgument, "update mask is required")
227		}
228	
229		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
230			UserID: &userID,
231			Key:    storepb.UserSetting_SHORTCUTS,
232		})
233		if err != nil {
234			return nil, err
235		}
236		if userSetting == nil {
237			return nil, status.Errorf(codes.NotFound, "shortcut not found")
238		}
239	
240		shortcutsUserSetting := userSetting.GetShortcuts()
241		shortcuts := shortcutsUserSetting.GetShortcuts()
242		var foundShortcut *storepb.ShortcutsUserSetting_Shortcut
243		newShortcuts := make([]*storepb.ShortcutsUserSetting_Shortcut, 0, len(shortcuts))
244		for _, shortcut := range shortcuts {
245			if shortcut.GetId() == shortcutID {
246				foundShortcut = shortcut
247				for _, field := range request.UpdateMask.Paths {
248					if field == "title" {
249						if request.Shortcut.GetTitle() == "" {
250							return nil, status.Errorf(codes.InvalidArgument, "title is required")
251						}
252						shortcut.Title = request.Shortcut.GetTitle()
253					} else if field == "filter" {
254						if err := s.validateFilter(ctx, request.Shortcut.GetFilter()); err != nil {
255							return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
256						}
257						shortcut.Filter = request.Shortcut.GetFilter()
258					}
259				}
260			}
261			newShortcuts = append(newShortcuts, shortcut)
262		}
263	
264		if foundShortcut == nil {
265			return nil, status.Errorf(codes.NotFound, "shortcut not found")
266		}
267	
268		shortcutsUserSetting.Shortcuts = newShortcuts
269		userSetting.Value = &storepb.UserSetting_Shortcuts{
270			Shortcuts: shortcutsUserSetting,
271		}
272		_, err = s.Store.UpsertUserSetting(ctx, userSetting)
273		if err != nil {
274			return nil, err
275		}
276	
277		return &v1pb.Shortcut{
278			Name:   constructShortcutName(user.Username, foundShortcut.GetId()),
279			Title:  foundShortcut.GetTitle(),
280			Filter: foundShortcut.GetFilter(),
281		}, nil
282	}
